//! IFC2X3 `ePSet_MapConversion` and `ePSet_ProjectedCRS` (#451).
//!
//! The fixtures under `test/fixtures/synthetic-georef/` are generated by
//! `tools/gen_georef_fixtures.py` from the buildingSMART Australasia "User
//! Guide for Geo-referencing in IFC" v2.0, §5.1 Tables 2 to 4 and the §5.2
//! example. The IFC2X3 file must resolve to the parameters its IFC4 twin
//! resolves to; the refusal fixtures and the in-memory edits below must be
//! refused with the typed error naming what is wrong. Nothing here needs
//! the `transform` feature.

use std::path::PathBuf;

use ifc_georef::{
    has_property_set_georeferencing, resolve_project_to_map, resolve_property_set_georeferencing,
    GeorefError, OperationKind, OperationSource, ProjectToMap,
};
use ifc_model::{Codec, EntityId, Model};
use ifc_step::StepCodec;

/// Every fixture's project length unit is the millimetre.
const MILLIMETRE: f64 = 0.001;

fn fixture_text(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../test/fixtures/synthetic-georef")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn parse(text: &str) -> Model {
    StepCodec
        .read_bytes(text.as_bytes())
        .expect("fixture parses")
}

fn fixture(name: &str) -> Model {
    parse(&fixture_text(name))
}

/// `epset_project_ifc2x3.ifc` with each line starting `prefix` (an entity
/// id such as `#14=`) replaced by its replacement.
fn edited_all(edits: &[(&str, &str)]) -> Model {
    let text = fixture_text("epset_project_ifc2x3.ifc");
    let mut lines: Vec<&str> = text.lines().collect();
    for (prefix, replacement) in edits {
        let line = lines
            .iter_mut()
            .find(|line| line.starts_with(prefix))
            .unwrap_or_else(|| panic!("no line {prefix}"));
        *line = replacement;
    }
    parse(&lines.join("\n"))
}

fn edited(prefix: &str, replacement: &str) -> Model {
    edited_all(&[(prefix, replacement)])
}

fn resolve(model: &Model) -> Result<Vec<ProjectToMap>, GeorefError> {
    resolve_property_set_georeferencing(model, MILLIMETRE)
}

/// The IFC4 twin's one `IfcMapConversion`.
fn ifc4_twin() -> ProjectToMap {
    let model = fixture("map_conversion_ifc4.ifc");
    let (id, _) = model
        .of_type("IFCMAPCONVERSION")
        .next()
        .expect("the twin states one conversion");
    resolve_project_to_map(&model, id, MILLIMETRE).expect("the IFC4 twin resolves")
}

#[test]
fn ifc2x3_project_sets_resolve_like_the_ifc4_entities() {
    let model = fixture("epset_project_ifc2x3.ifc");
    assert!(has_property_set_georeferencing(&model));
    let resolved = resolve(&model).expect("the project pair resolves");
    let [pset] = resolved.as_slice() else {
        panic!("the project pair alone is read, not the site decoy: {resolved:?}");
    };
    let entity = ifc4_twin();

    // Where the parameters came from differs ...
    assert_eq!(pset.source, OperationSource::PropertySet(EntityId(13)));
    assert_eq!(pset.source_crs, EntityId(13));
    assert_eq!(pset.operation, EntityId(20), "the ePSet_MapConversion set");
    assert_eq!(
        pset.target_crs.entity,
        EntityId(29),
        "the ePSet_ProjectedCRS set"
    );
    assert_eq!(pset.kind, OperationKind::MapConversion);
    assert_eq!(pset.kind, entity.kind);

    // ... and every resolved number and CRS field agrees exactly.
    assert_eq!(pset.eastings, entity.eastings);
    assert_eq!(pset.northings, entity.northings);
    assert_eq!(pset.orthogonal_height, entity.orthogonal_height);
    assert_eq!(pset.declared_scale, entity.declared_scale);
    assert_eq!(pset.x_axis_direction, entity.x_axis_direction);
    assert_eq!(pset.project_unit, entity.project_unit);
    assert_eq!(pset.map_unit, entity.map_unit);
    assert_eq!(pset.map_unit.metres_per_unit, 1.0);
    assert_eq!(
        pset.declared_map_unit().map(|u| u.metres_per_unit),
        entity.declared_map_unit().map(|u| u.metres_per_unit)
    );
    assert_eq!(pset.linear_part(), entity.linear_part());
    assert_eq!(pset.translation(), entity.translation());
    for crs in [&pset.target_crs, &entity.target_crs] {
        assert_eq!(crs.name.as_deref(), Some("EPSG:7856"));
        assert_eq!(crs.description.as_deref(), Some("GDA2020 / MGA zone 56"));
        assert_eq!(crs.geodetic_datum.as_deref(), Some("GDA2020"));
        assert_eq!(crs.vertical_datum.as_deref(), Some("AHD"));
        assert_eq!(crs.map_projection.as_deref(), Some("MGA"));
        assert_eq!(crs.map_zone.as_deref(), Some("56"));
        assert_eq!(crs.well_known_text, None);
    }

    // The guide's §5.2 reference point Ref2, local (116.611, 75.960, 0.834)
    // m (`map_point` takes project metres), lands within a millimetre of
    // its stated map position E 333906.644, N 6246834.938 (the example
    // rounds to the millimetre). The height differs from the guide's
    // 98.291 by the grid scale on Z, which IFC4 `IfcMapConversion` applies
    // and the example does not; the property sets follow IFC4.
    let [e, n, _] = pset.map_point([116.611, 75.960, 0.834]);
    assert!((e - 333_906.644).abs() < 1e-3, "{e}");
    assert!((n - 6_246_834.938).abs() < 1e-3, "{n}");
}

#[test]
fn sites_are_read_when_the_project_carries_no_sets() {
    let model = fixture("epset_sites_ifc2x3.ifc");
    let resolved = resolve(&model).expect("both site pairs resolve");
    let sources: Vec<OperationSource> = resolved.iter().map(|r| r.source).collect();
    let site_ids: Vec<EntityId> = model.of_type("IFCSITE").map(|(id, _)| id).collect();
    assert_eq!(
        sources,
        site_ids
            .iter()
            .map(|&id| OperationSource::PropertySet(id))
            .collect::<Vec<_>>()
    );
    assert_eq!(resolved[0].eastings, 333_780.622);
    assert_eq!(resolved[1].eastings, 334_000.0);
    assert_eq!(resolved[1].northings, 6_246_000.0);
}

#[test]
fn a_pair_split_across_project_and_site_is_refused() {
    let model = fixture("epset_split_pair_ifc2x3.ifc");
    let project = model.of_type("IFCPROJECT").next().expect("project").0;
    assert_eq!(
        resolve(&model),
        Err(GeorefError::IncompletePropertySets {
            host: project,
            missing: "ePSet_ProjectedCRS",
        })
    );
}

#[test]
fn eastings_that_are_not_a_length_measure_are_refused() {
    let model = fixture("epset_malformed_ifc2x3.ifc");
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::InvalidProperty {
            name: "Eastings",
            ..
        })
    ));
}

#[test]
fn a_missing_northings_is_refused() {
    let model = fixture("epset_missing_northings_ifc2x3.ifc");
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::MissingProperty {
            name: "Northings",
            ..
        })
    ));
}

#[test]
fn a_second_conversion_set_on_the_project_is_ambiguous() {
    // The site's decoy set (#41) re-attached to the project as well.
    let model = edited(
        "#42=",
        "#42=IFCRELDEFINESBYPROPERTIES('3Es3c8eA1Uh9R9q44P43nl',#5,$,$,(#34,#13),#41);",
    );
    assert_eq!(
        resolve(&model),
        Err(GeorefError::AmbiguousPropertySets {
            host: EntityId(13),
            name: "ePSet_MapConversion",
            sets: vec![EntityId(20), EntityId(41)],
        })
    );
}

#[test]
fn a_repeated_property_name_breaks_wr32() {
    let model = edited(
        "#20=",
        "#20=IFCPROPERTYSET('24qXbnes5SaQhTiTcqb5LC',#5,'ePSet_MapConversion',$,(#14,#15,#16,#17,#18,#19,#35));",
    );
    assert_eq!(
        resolve(&model),
        Err(GeorefError::RuleViolation {
            entity: EntityId(20),
            rule: "WR32 : IfcUniquePropertyName(HasProperties)",
        })
    );
}

#[test]
fn a_map_unit_that_names_no_si_length_unit_is_refused() {
    let model = edited(
        "#28=",
        "#28=IFCPROPERTYSINGLEVALUE('MapUnit',$,IFCLABEL('US survey foot'),$);",
    );
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::InvalidProperty { name: "MapUnit", property, .. }) if property == EntityId(28)
    ));
}

#[test]
fn an_omitted_map_unit_is_the_project_length_unit() {
    let model = edited(
        "#29=",
        "#29=IFCPROPERTYSET('3faM_bSTTRoOz5Hin7_aAf',#5,'ePSet_ProjectedCRS',$,(#22,#23,#24,#25,#26,#27));",
    );
    let [resolved] = resolve(&model).expect("resolves").try_into().expect("one");
    assert_eq!(resolved.declared_map_unit(), None);
    assert_eq!(resolved.map_unit, resolved.project_unit);
    // Eastings are then millimetres.
    assert_eq!(resolved.translation()[0], 333_780.622 * MILLIMETRE);
}

#[test]
fn a_length_whose_own_unit_disagrees_with_the_map_unit_is_refused() {
    // #6 is the millimetre; the map unit is the METRE.
    let model = edited(
        "#14=",
        "#14=IFCPROPERTYSINGLEVALUE('Eastings',$,IFCLENGTHMEASURE(333780.622),#6);",
    );
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::InvalidProperty { name: "Eastings", property, .. }) if property == EntityId(14)
    ));
    // Stating the map unit itself is accepted.
    let model = edited(
        "#14=",
        "#14=IFCPROPERTYSINGLEVALUE('Eastings',$,IFCLENGTHMEASURE(333780.622),#7);",
    );
    assert_eq!(resolve(&model).expect("resolves")[0].eastings, 333_780.622);
}

#[test]
fn a_property_that_is_not_a_single_value_is_refused() {
    let model = edited(
        "#19=",
        "#19=IFCPROPERTYENUMERATEDVALUE('Scale',$,(IFCREAL(1.)),$);",
    );
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::InvalidProperty { name: "Scale", .. })
    ));
}

#[test]
fn a_crs_without_a_name_is_refused() {
    let model = edited("#22=", "#22=IFCPROPERTYSINGLEVALUE('Name',$,$,$);");
    assert_eq!(
        resolve(&model),
        Err(GeorefError::MissingProperty {
            property_set: EntityId(29),
            name: "Name",
        })
    );
}

#[test]
fn a_degenerate_axis_and_a_non_positive_scale_are_refused() {
    let model = edited_all(&[
        (
            "#17=",
            "#17=IFCPROPERTYSINGLEVALUE('XAxisAbscissa',$,IFCREAL(0.),$);",
        ),
        (
            "#18=",
            "#18=IFCPROPERTYSINGLEVALUE('XAxisOrdinate',$,IFCREAL(0.),$);",
        ),
    ]);
    assert_eq!(
        resolve(&model),
        Err(GeorefError::DegenerateAxis {
            entity: EntityId(20)
        })
    );
    let model = edited(
        "#19=",
        "#19=IFCPROPERTYSINGLEVALUE('Scale',$,IFCREAL(0.),$);",
    );
    assert!(matches!(
        resolve(&model),
        Err(GeorefError::InvalidScale { entity, .. }) if entity == EntityId(20)
    ));
}

#[test]
fn only_an_ifc2x3_header_is_read_through_property_sets() {
    let text = fixture_text("epset_project_ifc2x3.ifc").replace("('IFC2X3')", "('IFC4')");
    assert_eq!(
        resolve(&parse(&text)),
        Err(GeorefError::UnsupportedSchema {
            token: "IFC4".into()
        })
    );
}

#[test]
fn a_model_without_the_sets_resolves_to_nothing() {
    let text = fixture_text("epset_project_ifc2x3.ifc")
        .replace("'ePSet_MapConversion'", "'Pset_Other'")
        .replace("'ePSet_ProjectedCRS'", "'Pset_Another'")
        .replace("'ePset_MapConversion'", "'Pset_Third'")
        .replace("'ePset_ProjectedCRS'", "'Pset_Fourth'");
    let model = parse(&text);
    assert!(!has_property_set_georeferencing(&model));
    assert_eq!(resolve(&model), Ok(Vec::new()));
}

#[test]
fn the_project_scale_must_be_finite_and_positive() {
    let model = fixture("epset_project_ifc2x3.ifc");
    for scale in [0.0, -1.0, f64::NAN] {
        assert!(matches!(
            resolve_property_set_georeferencing(&model, scale),
            Err(GeorefError::InvalidUnit { .. })
        ));
    }
}
